import{_ as e,a,o as d,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Return Reasons","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/return-reasons/index.md","filePath":"api/graphql-api/admin/settings/return-reasons/index.md","lastUpdated":1786429091000}'),s={name:"api/graphql-api/admin/settings/return-reasons/index.md"};function o(n,t,i,c,h,l){return d(),a("div",null,t[0]||(t[0]=[r('<h1 id="return-reasons" tabindex="-1">Return Reasons <a class="header-anchor" href="#return-reasons" aria-label="Permalink to &quot;Return Reasons&quot;">​</a></h1><p>The <strong>Return Reasons</strong> menu is part of the store&#39;s <strong>RMA (Returns) settings</strong>. Return / cancel reasons the RMA form offers a customer when they open a return. Each reason has a title, a display position, an active status, an <code>isAdmin</code> flag, and a <code>resolutionType</code> — the set of return actions the reason allows.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./queries/list.html">List</a></td><td><code>adminRmaReasons</code> query</td></tr><tr><td><a href="./queries/get.html">Get</a></td><td><code>adminRmaReason(id:)</code> query</td></tr><tr><td><a href="./mutations/create.html">Create</a></td><td><code>createAdminRmaReason</code> mutation</td></tr><tr><td><a href="./mutations/update.html">Update</a></td><td><code>updateAdminRmaReason</code> mutation</td></tr><tr><td><a href="./mutations/delete.html">Delete</a></td><td><code>deleteAdminRmaReason</code> mutation</td></tr><tr><td><a href="./mutations/mass-delete.html">Mass delete</a></td><td><code>createAdminRmaReasonMassDelete</code> mutation</td></tr><tr><td><a href="./mutations/mass-update-status.html">Mass update status</a></td><td><code>createAdminRmaReasonMassUpdateStatus</code> mutation</td></tr></tbody></table><p>List queries are cursor-paginated Relay connections.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>title</code></td><td>The reason label shown to the customer.</td></tr><tr><td><code>status</code></td><td><code>1</code> active, <code>0</code> inactive.</td></tr><tr><td><code>position</code></td><td>Sort order in the returns form.</td></tr><tr><td><code>isAdmin</code></td><td><code>1</code> if the reason was created by an admin, <code>0</code> if it is a seeded reason.</td></tr><tr><td><code>resolutionType</code></td><td>The return actions this reason allows — an array of <code>return</code> and/or <code>cancel_items</code>.</td></tr><tr><td><code>message</code></td><td><code>null</code> on create / update / read; populated only on the delete confirmation.</td></tr></tbody></table><p>Select <code>_id</code> for the numeric id; <code>id</code> is the resource IRI.</p><h2 id="how-rma-settings-fit-together" tabindex="-1">How RMA settings fit together <a class="header-anchor" href="#how-rma-settings-fit-together" aria-label="Permalink to &quot;How RMA settings fit together&quot;">​</a></h2><p>Reasons, statuses and custom fields shape the <strong>returns form</strong> the customer fills in when opening a return; <strong>rules</strong> set the <strong>return window</strong> that decides whether a product is still eligible. Together they make up the store&#39;s RMA (Returns) settings.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>Create</td><td><code>sales.rma.reasons.create</code></td></tr><tr><td>Update / mass update status</td><td><code>sales.rma.reasons.edit</code></td></tr><tr><td>Delete / mass delete</td><td><code>sales.rma.reasons.delete</code></td></tr></tbody></table><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',13)]))}const p=e(s,[["render",o]]);export{m as __pageData,p as default};
